// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint96 amount) public {
        vm.assume(recipient != address(0));
        c.init(address(0x1), address(0x2), address(0x3));
        vm.prank(address(0xa));
        c.newGrantProposal(recipient, amount);
        uint256 pid = c.proposalCount();
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(pid);
        assertTrue(storedRecipient == recipient);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() != address(0));
    }
}
